import {ITEMS,ROLES,ROUTES,LAUNCHERS,SOURCES,GUIDE} from './data.js';
import * as E from './engine.js';
import {ChipAudio} from './audio.js';
const root=document.querySelector('#root'),modal=document.querySelector('#modal'),body=document.querySelector('#modal-body'),audio=new ChipAudio();
let game=null,saved=null,menu=null,home=true,letterActive=false,letterStart=0,playersPick=1,paperPage=0,launching=false,legacySave=false;try{legacySave=!!(localStorage.getItem('beeyond-v6')||localStorage.getItem('beeyond-v5'));saved=JSON.parse(localStorage.getItem('beeyond-v11'));if(!E.validSave(saved))saved=null;}catch{}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const b=(text,action,cls='',disabled=false)=>`<button data-action="${action}" class="${cls}" ${disabled?'disabled':''}>${text}</button>`;
const bee=(mood='sleep')=>`<img class="bee gm-bee mood-${mood}" src="assets/gamemaker-v11/spr_bees_${mood==='risk'?2:mood==='happy'?3:mood==='sleep'?1:0}.png" alt="${mood==='risk'?'Queens under stress':'Bumblebee queens'}">`;
function toast(s){const t=document.querySelector('#toast');t.textContent=s;t.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.style.display='none',3300);}
function logMissionStart(){E.log(game,`Funding letter received: ${E.stats(game).budget} credits from Aurelia. Mission accepted.`);}
function save(){saved=structuredClone(game);try{localStorage.setItem('beeyond-v11',JSON.stringify(game));}catch{toast('Could not save. Keep this tab open.');}}
function update(s){game=s;save();render();if(menu)drawMenu();}
function objective(){if(!game.parts.some(x=>x.startsWith('chamber')))return ['Meet your tiny passengers','Choose a chamber at Biology to protect them.'];if(!game.grants.includes(0))return ['Review your first design','At Mission Lead, review chamber, power and mass for 150 credits.'];if(!game.grants.includes(1))return ['Compare routes to Mars','At Mission Lead, compare both routes to claim 200 credits.'];if(E.errors(game).length)return ['Adjust your spacecraft','Mission Lead lists the remaining launch requirements.'];return ['Ready for the mission','Improve your instruments or launch at Mission Lead.'];}
function hud(){const t=E.stats(game);return `<header class="hud"><div class="brand">BEEYOND MARS <small> / AURELIA</small></div><div class="metrics"><span>FUNDS <strong>${t.budget}</strong></span><span>MASS <strong>${t.kg.toFixed(1)}/250 kg</strong></span><span>POWER <strong>${t.use}/${t.power} W</strong></span><span>DV <strong>${t.dv.toFixed(2)}/${E.route(game).dv}</strong></span></div><div class="hud-tools">${b('LOGBOOK','journal')}${b('MENU','pause')}</div></header>`;}
const LETTER=`Dear team,\n\nWe are happy to tell you that your research proposal "BeeYond Mars: dormant bumblebee queens for future Martian greenhouses" has been FUNDED.\n\nYou receive 900 credits to design the spacecraft. Passing the design reviews (CML 2 and 3) unlocks 350 more.\n\nYour mission: fly fertilized, dormant Bombus terrestris queens to Mars and keep them in good condition until arrival. Use the real NASA trajectory data and record everything in your mission logbook. When you arrive, your results become a scientific paper: the reviewers will decide if it gets published.\n\nGood luck!\nDr. Pollen, Director`;
function render(){if(game)audio.setTrack(['voyage','report','greenhouse'].includes(game.phase)?'voyage':'music');if(home){root.innerHTML=`<section class="title"><div class="title-card"><span class="eyebrow">A TINY LIFE * A HUGE JOURNEY</span>${bee('active')}<h1>BEEYOND MARS</h1><p>Explore the lab, design a spacecraft and look after dormant bumblebee queens on an educational mission to Mars.</p><div class="actions">${b('NEW MISSION','new','primary')}${b('GUIDE AND SOURCES','learn')}</div><button class="title-music" data-action="music-toggle">MUSIC: ${audio.music>0?'ON':'OFF'}</button><small>1–4 players on one device · NASA Space Apps 2026<br>Art: AI-assisted, marked AI · Fictional agency Aurelia · No NASA logos</small></div></section>`;return;}if(letterActive){root.innerHTML=letterScreen();return;}
root.innerHTML=`<section class="game">${hud()}<div class="world">${launching?liftoff():game.phase==='lab'||game.phase==='launch'?lab():game.phase==='voyage'?flight():game.phase==='greenhouse'?greenhouse():result()}</div><footer class="dock">${game.phase==='lab'||game.phase==='launch'?`<div class="actions">${ROLES.map((r,i)=>b(['BIOLOGY','ENGINEERING','COMMUNICATIONS','MISSION LEAD'][i],`station:${[1,0,2,3][i]}`)).join('')}</div><span class="hint">WASD / ARROWS: WALK · E: INTERACT<br>Or click a station. ${game.players} player${game.players===1?'':'s'}: ${game.players===1?'you hold every role.':'each role installs its own parts.'}</span>`:`<span class="hint">Every decision changes the mission outcome.</span><div class="actions">${b('LOGBOOK','journal')}${b('GUIDE AND SOURCES','learn')}</div>`}</footer></section>`;}
function letterScreen(){const n=Math.min(LETTER.length,Math.floor((performance.now()-letterStart)/17)*3);return `<section class="letter-screen"><div class="letter-paper"><h2>AURELIA SPACE AGENCY</h2><p class="letter-sub">Office of Pollinator Research * fictional space agency</p><hr><p>To: the BeeYond Mars team<br>Subject: research proposal FUNDED</p><p class="letter-copy" id="letter-copy">${esc(LETTER.slice(0,n)).replaceAll('\n','<br>')}</p><div id="letter-stamp">${n>=LETTER.length?'<div class="funded-stamp">FUNDED<br><small>900 CREDITS</small></div>':''}</div></div><aside class="letter-side">${bee('happy')}<h2>YOU WON THE FUNDS!</h2><p>The research grant is yours. Now build a spacecraft that can carry the queens.</p><p class="letter-limit">This mission is hypothetical. Diapause data come from studies on Earth. No one has shown that bumblebee queens survive an interplanetary trip; the game uses a simplified model to teach engineering decisions.</p><b>PEOPLE ON THIS DEVICE</b><div class="player-picks">${[1,2,3,4].map(n=>b(String(n),`players:${n}`,playersPick===n?'selected':'' )).join('')}</div><p>${playersPick===1?'1 player: you hold all four roles.':`${playersPick} players take turns at stations. Each role installs its own parts; the budget is shared.`}</p><div class="letter-actions">${n<LETTER.length?b('READ ALL','readall'):''}${b('ACCEPT MISSION','accept-letter','primary')}</div></aside></section>`;}
let letterTicker=null;function updateLetterReveal(){const n=Math.min(LETTER.length,Math.floor((performance.now()-letterStart)/17)*3),copy=document.querySelector('#letter-copy');if(copy)copy.innerHTML=esc(LETTER.slice(0,n)).replaceAll('\n','<br>');if(n>=LETTER.length){const stamp=document.querySelector('#letter-stamp');if(stamp&&!stamp.innerHTML)stamp.innerHTML='<div class="funded-stamp">FUNDED<br><small>900 CREDITS</small></div>';clearInterval(letterTicker);letterTicker=null;}}

function lab(){const q=objective(),tip=E.hints(game)[0];return `<canvas id="world" width="640" height="352" aria-label="Aurelia lab. Use WASD or arrow keys to walk, E to interact, or select a station button."></canvas><div class="quest"><span class="eyebrow">YOUR NEXT STEP</span><b>${q[0]}</b><small>${q[1]}</small><small class="tip"><b>TIP</b> ${tip}</small></div><div class="bee-monitor">${bee()}<small>QUEENS IN DIAPAUSE<br>Experimental biological payload</small></div><div class="dpad"><button data-move="ArrowUp" aria-label="Up">↑</button><button data-move="ArrowLeft" aria-label="Left">←</button><button data-move="ArrowDown" aria-label="Down">↓</button><button data-move="ArrowRight" aria-label="Right">→</button></div>`;}
function flight(){const f=game.flight;return `<div class="flight"><img class="flight-ship" src="assets/gamemaker-v11/spr_equip_6.png" alt="Spacecraft" style="--progress:${game.day/E.totalDays(game)*100}%"><div><span class="eyebrow">CRUISE TO MARS</span><h2>Day ${game.day} of ${E.totalDays(game)}</h2><div class="progress"><i style="width:${game.day/E.route(game).days*100}%"></i></div></div><div class="chamber"><small class="eyebrow">DID YOU KNOW?</small><p class="fact">${['NASA: a trip to Mars takes about 7 to 10 months.','NASA Trajectory Browser: your route was computed for real planet positions.','NASA Mars Fact Sheet: Mars gets about 43% of the sunlight Earth gets.','ESA: a radio signal takes 4 to 24 minutes to reach Mars.','NASA Deep Space Network: three sites on Earth listen to deep-space missions.','Smithsonian: in 1984, 3,300 honeybees flew on the Space Shuttle (STS-41-C).','Bumblebee queens sleep (diapause) through winter for about 6 to 9 months.','Earth and Mars line up for a launch window about every 26 months.'][Math.floor(game.day/30)%8]}</p>${bee(f.risk>35?'risk':'sleep')}<b>${f.risk>35?'Needs attention':'Cargo in diapause'}</b><div class="statusline">${f.temp.toFixed(1)} °C · ${f.humidity.toFixed(0)}% RH</div></div><div><div class="metrics"><span>Risk <strong>${Math.round(f.risk)}/100</strong></span><span>Battery <strong>${Math.round(f.charge)} Wh</strong></span><span>Memory <strong>${Math.round(f.stored)}/128 MB</strong></span><span>Received <strong>${Math.round(f.sent)} MB</strong></span><span>Lost <strong>${Math.round(f.lost)} MB</strong></span><span>Signal <strong>${Math.round(E.delay(game))} min</strong></span><span>Ship <strong>${Math.round(f.integrity)}%</strong></span></div><div class="flight-bottom"><div><b>${f.pending?'The spacecraft needs a decision':'Observe, learn and continue'}</b><p>${f.pending?'Time is paused until you choose a response.':`Sunlight now gives ${Math.round(f.lastGen??E.stats(game).arrivalPower)} W for ${E.stats(game).use} W of use. Ship integrity ${Math.round(f.integrity)}%, repair actions ${f.repairs}.`}</p></div>${b(f.pending?'Resolve incident':`Advance ${Math.min(30,E.route(game).days-game.day)} days`,f.pending?'event':'advance','primary')}</div></div></div>`;}
function liftoff(){return `<div class="result liftoff"><div class="launch-scene"><img class="launch-background" src="assets/gamemaker-v11/spr_bg_launchpad_0.png" alt="Aurelia launch pad"><img class="rocket" src="assets/gamemaker-v11/spr_rocket_0.png" alt="Aurelia spacecraft"></div><h2>LAUNCHING</h2><p>T−3 · T−2 · T−1 · Liftoff!</p>${b('Skip','skip','primary')}</div>`;}
function greenhouse(){const g=game.green,step=E.greenSteps[g.step];if(g.done){const r=E.greenResult(game);return `<div class="result greenhouse-result"><h2>${r.title}</h2><p>Colony index ${r.colony}/100 · ${r.science} science · ${r.pollinated?'Tomato flowers pollinated.':'No pollination test.'}</p><div class="actions">${b('Open updated paper','paper','primary')}${b('Redesign mission','redesign')}</div></div>`;}return `<div class="result"><span class="eyebrow">SEALED HYPOTHETICAL GREENHOUSE · ${g.cells} ENERGY CELLS</span><span class="eyebrow">NEXT PHASE · HYPOTHETICAL EXTENSION</span><h2>MARS GREENHOUSE</h2><h3>${step.title}</h3><p>${step.text}</p><p>Colony index ${Math.round(g.colony)}/100 · ${g.cells} energy cells</p><article class="card"><h3>${step.careful}</h3><p>${step.carefulDesc}</p>${b('Choose careful option','green:careful','primary',g.cells<1)}</article><article class="card"><h3>${step.free}</h3><p>${step.freeDesc}</p>${b('Choose free option','green:free')}</article><p class="notice">Did you know? ${step.fact}</p><p class="notice">Sealed greenhouse: nothing is released on Mars (planetary protection).</p>${b('BACK TO THE REPORT','green:back')}</div>`;}
function result(){const r=E.report(game),f=game.flight;const title={success:'Mars in sight!',partial:'Arrival with lessons learned',failure:'Time to redesign'};return `<div class="result report-screen"><div class="report-card"><span class="eyebrow">MISSION REPORT / ATTEMPT ${game.attempt}</span>${bee(r.kind==='success'?'happy':r.kind==='partial'?'':'risk')}<h2>${title[r.kind]}</h2><p>${r.reason==='power'?'Power failed for two consecutive stages. Reduce demand or add generation.':r.reason==='climate'?'Chamber conditions increased cargo risk. Compare active climate control, sensors and onboard responses.':r.reason==='data'?'The spacecraft arrived with incomplete observations. Compare transmission, storage and data choices.':r.reason==='comms'?"Contact with Earth was lost for good: no high-gain antenna and no backup comms when the signal dropped. Telemetry froze and the mission failed early.":r.reason==='systems'?'A mechanical failure kept damaging the ship. A repair toolkit lets you fix it with one logbook action.':'The design balanced power, climate and communications during autonomous flight.'}</p><div class="metrics"><span>${game.day}/${E.totalDays(game)} days</span><span>Cargo ${r.status}</span><span>Risk ${Math.round(f.risk)}/100</span><span>${Math.round(f.sent)} MB received</span><span>${Math.round(f.lost)} MB lost</span><span>${r.science?`+${r.science} science`:''}</span><span>${r.score} points</span><span>Climate ${f.temp.toFixed(1)} °C / ${Math.round(f.humidity)}% RH</span><span>Energy ${Math.round(f.energy/1000)} kWh</span><span>Ship ${Math.round(f.integrity)}%</span></div><p>What would you change? Redesign while keeping equipment and earned grants.</p><div class="actions">${b('Redesign mission','redesign','primary')}${b('Open mission paper','journal')}${E.greenCan(game)?b('Next phase: Greenhouse','green:start'):''}${b('Download report','download')}</div><small>Hypothetical educational model; it does not show real survival in space. Landing is not simulated; the greenhouse is a hypothetical extension.</small></div></div>`;}
function open(which){keys.clear();if(which==='journal')paperPage=game?.phase==='report'?3:0;menu=which;drawMenu();if(!modal.open)modal.showModal();}
function close(){modal.close();menu=null;keys.clear();}
function paperHtml(){const s=game,r=s.flight?E.report(s):null,cc=r?E.conclusions(s):null,t=E.stats(s),route=E.route(s),parts=s.parts.map(id=>ITEMS.find(i=>i.id===id)?.name[0]).join(', ')||'no equipment yet';let content='';if(paperPage===0)content=`<h2>Transport of dormant <i>Bombus terrestris</i> queens to Mars</h2><p>BeeYond Mars team · Aurelia Space Agency (fictional) · Attempt ${s.attempt} · Seed ${s.seed}</p><h3>ABSTRACT</h3><p>${r?`We flew ${parts} on ${route.name[0]} (${s.day} days). Result: ${r.kind.toUpperCase()}, cargo ${r.status}, risk ${Math.round(s.flight.risk)}/100.`:`We are designing a spacecraft. Current payload: ${parts}; ${t.kg.toFixed(1)} kg; ${t.use}/${t.power} W; delta-v ${t.dv.toFixed(2)} km/s.`}</p><h3>1. INTRODUCTION</h3><p>We investigate a hypothetical transport of dormant bumblebee queens. Their survival in interplanetary flight remains an open scientific question. The risk score is a game index, never a survival probability.</p>`;if(paperPage===1)content=`<h3>2. METHODS</h3><p>Spacecraft: ${parts}. Mass ${t.kg.toFixed(1)} kg; power ${t.use} W of ${t.power} W. Delta-v = 7.0 − 0.008 × mass = ${t.dv.toFixed(2)} km/s.</p><p>Trajectory: ${route.name[0]}, ${route.depart} to ${route.arrive}, ${route.days} days, ${route.dv} km/s (NASA Ames Trajectory Browser values supplied by the team).</p><h3>3. RESULTS</h3>${s.flight?.stages.map(x=>`<p>Day ${x.day}: ${x.gen}/${x.use} W · battery ${x.charge} Wh · ${x.temp.toFixed(1)} °C · ${x.hum}% RH · risk ${x.risk} · received ${x.sent} MB · integrity ${x.integ}%</p>`).join('')||'<p>No flight data recorded yet.</p>'}`;if(paperPage===2)content=`<h3>3.1 EVENTS AND DECISIONS</h3>${s.log.filter(x=>/alarm|signal|impact|milestone|launch|thermal|comms|mech/i.test(x.en)).map(x=>`<p>Day ${x.day}. ${esc(x.en)}</p>`).join('')||'<p>No events yet.</p>'}<h3>4. DISCUSSION</h3><p>${r?`The mission result was ${r.kind}; ${r.reason} was the primary outcome. This educational model does not demonstrate biological survival.`:'Discussion will be generated after the mission.'}</p><h3>REFERENCES</h3>${SOURCES.filter(x=>x.url).map(x=>`<p><a href="${x.url}" target="_blank" rel="noopener">${x.title}</a></p>`).join('')}`;if(paperPage===3)content=cc?`<h2>5. CONCLUSIONS</h2>${cc.findings.map(x=>`<p>${esc(x)}</p>`).join('')}${s.green?.done?`<p>Greenhouse follow-up: ${E.greenResult(s).title}, colony index ${E.greenResult(s).colony}/100; ${E.greenResult(s).science} science.</p>`:''}`:'<h2>5. CONCLUSIONS</h2><p>Conclusions will be generated after flight.</p>';if(paperPage===4)content=cc?`<h2>PEER REVIEW</h2><p class="stamp">${cc.verdict} · Journal of Pollinator Spaceflight</p><p>${cc.vtext}</p><h3>WHAT WORKED</h3>${cc.good.map(x=>`<p>+ ${esc(x)}</p>`).join('')}<h3>WHAT TO IMPROVE</h3>${cc.fix.map(x=>`<p>› ${esc(x)}</p>`).join('')}`:'<h2>PEER REVIEW</h2><p>Review appears after flight.</p>';return `<div class="paper">${content}</div><p>PAGE ${paperPage+1}/5</p><div class="actions">${b('‹','paperpage:-1','',paperPage===0)}${b('›','paperpage:1','',paperPage===4)}</div>`;}
function drawMenu(){let html='';if(menu==='new'){html=`<h2>Your mission begins</h2><p>Aurelia has funded your team with 900 credits. Balance power, mass and communications; design reviews unlock more funding.</p><label>Players on this device <select id="players"><option value="1">1 · all roles</option><option value="2">2 · local turns</option><option value="3">3 · local turns</option><option value="4">4 · local turns</option></select></label><p>${saved?'Starting a mission begins a new v11 save. Older saves are kept separately.':'Walk to stations or select them directly.'}</p>${b('Accept mission','accept','primary')}`;}
else if(menu==='briefing'){html=`<span class="eyebrow">AURELIA SPACE AGENCY · FICTIONAL</span><h2>Dear research team,</h2><p>Your proposal has been funded. You receive 900 credits to design a spacecraft for dormant <i>Bombus terrestris</i> queens. Passing the CML-inspired design reviews unlocks 350 additional credits.</p><p>Use the route data, record your decisions and prepare a paper for peer review. This is a hypothetical educational mission.</p>${b('Enter the laboratory','commence','primary')}`;}
else if(menu==='audio'){html=`<h2>Music and sound</h2><p>Original chiptune melody, square-wave arpeggios and triangle bass.</p><label>Music <input aria-label="Music volume" type="range" min="0" max="0.6" step="0.01" data-volume="music" value="${audio.music}"></label><label>Sound effects <input aria-label="Sound volume" type="range" min="0" max="0.8" step="0.01" data-volume="sfx" value="${audio.sfx}"></label>${b('Test sound','test-sound')}${b('Mute all','mute')}<p><small>Settings are saved. Audio pauses when the tab is hidden. Set a slider to zero to mute it.</small></p>`;}
else if(menu==='pause'){html=`<h2>Mission paused</h2><p>Mission progress saves automatically in this browser.</p><div class="actions">${b('LOGBOOK (PAPER)','journal')}${b(`MUSIC: ${audio.music>0?'ON':'OFF'}`,'music-toggle')}${b(`SOUND FX: ${audio.sfx>0?'ON':'OFF'}`,'sfx-toggle')}</div><label>Volume ${Math.round((audio.master??.5)*100)}% <input type="range" min="0" max="1" step="0.1" data-volume="master" value="${audio.master??.5}"></label><div class="actions">${b('GUIDE AND SOURCES','learn')}${b('FULL SCREEN (F11)','fullscreen')}${b('BACK TO TITLE','home')}</div>`;}
else if(menu==='journal'){html=paperHtml();}
else if(menu==='learn'){html=`<h2>GUIDE AND SOURCES</h2><div class="cards">${GUIDE.map(([title,description])=>`<article class="card"><h3>${title}</h3><p>${description}</p></article>`).join('')}</div><h3>NASA, science and team references</h3>${SOURCES.map(s=>`<article class="card source-card"><h3>${s.title}</h3><small>${s.label}${s.url?` · <a href="${s.url}" target="_blank" rel="noopener noreferrer">Open source</a>`:''}</small><p>${s.use}</p></article>`).join('')}<p class="notice">${SOURCES.at(-1).use}</p><p>Credits: concept, story and mechanics by BeeYond Mars. Bee sprites and scene art are AI-assisted and carry a visible AI mark. Code and original chiptune music were made with AI assistance and reviewed by the team. Aurelia is fictional. No NASA logos.</p>`;}
else if(menu==='event'){const thermal=game.flight.pending==='thermal',comms=game.flight.pending==='comms';html=`<span class="eyebrow">DECISION FOR ${game.flight.pending==='thermal'?'BIOLOGY':game.flight.pending==='comms'?'COMMUNICATIONS':'ENGINEERING'} · DAY ${game.day}</span><h2>${thermal?'ALERT! HIVE TEMPERATURE OUT OF RANGE':comms?"SIGNAL LOST WITH NASA'S DEEP SPACE NETWORK":'MINOR IMPACT DETECTED!'}</h2><img class="event-warning" src="assets/gamemaker-v11/spr_fx_warning_0.png" alt="Warning"><p>${thermal?'The chamber temperature is out of range. Choose an onboard response.':comms?'The antenna lost its signal. Choose how to respond to the loss of contact.':'A minor impact damaged the spacecraft. Choose how to respond.'}</p><div class="cards">${E.options(game).map(o=>`<article class="card"><h3>${o.name[1]}</h3><p>${o.desc[1]}</p>${b('Choose response',`resolve:${o.id}`,'primary',o.disabled)}</article>`).join('')}</div>`;}
else if(menu.startsWith('station:')){const role=Number(menu.split(':')[1]);html=`<span class="eyebrow">STATION ${ROLES[role][1].toUpperCase()}</span><h2>${['Build your spacecraft','Protect the queens','Communicate with Earth','Prepare for launch'][role]}</h2>`;if(role!==3){html+=`<p>${['Plan generation for arrival, when solar output is lower.','The queens travel in diapause. Active climate control uses more power.','Science data helps evaluate the mission. Instruments also use power.'][role]}</p><div class="cards">${ITEMS.filter(i=>i.role===role).map(i=>`<article class="card ${game.parts.includes(i.id)?'selected':''}"><img src="assets/gamemaker-v11/spr_equip_${i.icon}.png" alt=""><h3>${i.name[1]}</h3><p>${i.desc[1]}</p><small>${i.cost} credits · ${i.kg} kg · ${i.gen?'+'+i.gen:i.w} W</small>${b(game.parts.includes(i.id)?'Remove equipment':'Install',`item:${i.id}`,game.parts.includes(i.id)?'':'primary')}</article>`).join('')}</div><p class="statusline">Available credits: ${E.stats(game).budget} credits. Equipment can be removed for a full refund.</p>`;}
else{const errors=E.errors(game),t=E.stats(game);html+=`<div class="actions">${b(game.grants.includes(0)?'✓ CML 2 approved':'+150 · CML 2 review','grant:0','',game.grants.includes(0))}${b(game.grants.includes(1)?'✓ CML 3 approved':'+200 · CML 3 review','grant:1','',game.grants.includes(1))}</div><p class="statusline">Install a chamber, claim the first review, compare all transfer options, then claim the second review.</p><div class="cards">${ROUTES.map(r=>`<article class="card ${game.route===r.id?'selected':''}"><h3>${r.name[1]}</h3><p>${r.depart} → ${r.arrive}</p><p>${r.days} days · ${r.inj} + ${r.post} = ${r.dv} km/s</p><small>Your spacecraft: ${E.stats(game).dv.toFixed(2)} km/s</small><p>${r.note}</p>${b(`${game.compared.includes(r.id)?'✓ ':''}Review and select`, `route:${r.id}`)}</article>`).join('')}</div><p class="statusline">Medium Lift rocket · 250 kg capacity · 7.0 km/s · 600 W</p><div class="notice ${errors.length?'bad':''}">${errors.length?errors.map(e=>esc(e[1])).join('<br>'):'✓ Chamber, mass, arrival power, trajectory and budget are compatible.'}<br>Arrival power: ${Math.round(t.arrivalPower)} W · demand ${t.use} W.${t.arrivalPower<t.use?'<br>Warning: battery reserve must cover the arrival power deficit.':''}</div>${b('Launch to Mars','launch','primary',E.milestone(game)<4)} <small>Requires both reviews and a compatible design.</small>`;}}
body.innerHTML=html;}
async function action(a){const [key,id]=a.split(':');if(key!=='fullscreen'){try{await audio.start();}catch{toast('El navegador no pudo activar el audio.');}}audio.effect();if(key==='close')return close();if(key==='skip'){launching=false;render();return;}if(key==='fullscreen'){try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{toast('Fullscreen no disponible. El juego ya ocupa la ventana.');}return;}if(key==='new'){home=false;letterActive=true;playersPick=1;letterStart=performance.now();letterTicker=setInterval(()=>{if(letterActive)updateLetterReveal();else{clearInterval(letterTicker);letterTicker=null;}},17);render();return;}if(key==='music-toggle'){audio.set('music',audio.music>0?0:.5);render();return;}if(key==='players'){playersPick=Number(id);render();return;}if(key==='readall'){letterStart=performance.now()-LETTER.length*17/3;updateLetterReveal();return;}if(key==='accept-letter'){clearInterval(letterTicker);letterActive=false;game=E.fresh(playersPick);logMissionStart();save();render();audio.effect('equip');return;}if(key==='sfx-toggle'){audio.set('sfx',audio.sfx>0?0:.5);drawMenu();return;}if(['audio','pause','journal','learn','event'].includes(key))return open(key);if(key==='green'){if(id==='back'){game.phase='report';save();render();return;}if(id==='start'){game=E.greenStart(game);save();render();return;}game=E.greenChoose(game,id==='careful');save();render();return;}if(key==='paper')return open('journal');if(key==='paperpage'){paperPage=Math.max(0,Math.min(4,paperPage+Number(id)));drawMenu();return;}if(key==='test-sound'){audio.effect('success');return;}if(key==='mute'){audio.set('music',0);audio.set('sfx',0);return drawMenu();}if(key==='continue'){game=structuredClone(saved);launching=false;if(game.phase==='launch')game.phase='lab';home=false;render();return;}if(key==='home'){close();launching=false;home=true;render();return;}if(key==='station'){game.role=Number(id);save();return open(a);}if(key==='item'){const next=E.toggle(game,id);if(next===game){toast('Insufficient credits. Remove equipment or complete a review.');audio.effect('error');}else audio.effect('equip');update(next);return;}if(key==='grant'){const next=E.claim(game,Number(id));if(next.grants.length===game.grants.length)toast(id==='0'?'Install a chamber and check power and payload capacity.':'Complete the first review and compare both routes.');else{toast('¡Credits de investigación received!');audio.effect('success');}update(next);return;}if(key==='route'){update(E.selectRoute(game,id));return;}if(key==='launch'){const next=E.launch({...game,phase:'launch'});if(next.phase==='voyage'){close();game=next;launching=true;save();render();audio.effect('launch');setTimeout(()=>{launching=false;render();},4000);}return;}if(key==='advance'){update(E.advance(game));audio.effect('advance');if(game.flight.pending)open('event');else if(game.phase==='report')open('journal');return;}if(key==='resolve'){const next=E.resolve(game,id);close();update(next);if(next.phase==='report'){open('journal');}return;}if(key==='redesign'){update(E.redesign(game));return;}if(key==='download'){const blob=new Blob([JSON.stringify({report:E.report(game),mission:game},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='BeeYondMars-informe.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-action]');if(target)action(target.dataset.action);});document.addEventListener('input',e=>{if(e.target.dataset.volume)audio.set(e.target.dataset.volume,e.target.value);});document.addEventListener('change',e=>{if(e.target.id==='launcher'){const next=E.chooseLauncher(game,e.target.value);if(next===game)toast('Insufficient credits for this launcher.');update(next);}});modal.addEventListener('cancel',e=>{e.preventDefault();close();});document.addEventListener('visibilitychange',()=>{keys.clear();document.hidden?audio.pause():audio.resume();});window.addEventListener('blur',()=>keys.clear());
const bg=new Image();bg.src='assets/gamemaker-v11/spr_lab_0.png';const crewFrames=Array.from({length:16},(_,i)=>{const im=new Image();im.src=`assets/gamemaker-v11/spr_crew_${i}.png`;return im;});let pos={x:310,y:180},direction=0,last=0,frame=0;const keys=new Set(),stations=[{x:130,y:294,role:0},{x:145,y:145,role:1},{x:512,y:145,role:2},{x:510,y:293,role:3}];
function interact(){const s=stations.reduce((a,b)=>Math.hypot(a.x-pos.x,a.y-pos.y)<Math.hypot(b.x-pos.x,b.y-pos.y)?a:b);if(Math.hypot(s.x-pos.x,s.y-pos.y)<110)action('station:'+s.role);else toast('Move closer to a station or use the buttons below.');}
document.addEventListener('keydown',e=>{if(home||modal.open)return;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d','W','A','S','D'].includes(e.key)){e.preventDefault();keys.add(e.key.toLowerCase());}if(!e.repeat&&['e','E','Enter',' '].includes(e.key)){e.preventDefault();if(game.phase==='lab')interact();}if(e.key==='Escape')open('pause');if(e.key==='F11'){e.preventDefault();if(!document.fullscreenElement)document.documentElement.requestFullscreen().catch(()=>toast('Fullscreen is unavailable.'));else document.exitFullscreen().catch(()=>{});}});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));document.addEventListener('pointerdown',e=>{if(e.target.dataset.move){e.preventDefault();e.target.setPointerCapture(e.pointerId);keys.add(e.target.dataset.move.toLowerCase());}});document.addEventListener('pointerup',()=>keys.clear());document.addEventListener('pointercancel',()=>keys.clear());
root.addEventListener('click',e=>{if(e.target.id!=='world')return;const r=e.target.getBoundingClientRect(),scale=Math.min(r.width/640,r.height/352),x=(e.clientX-r.left-(r.width-640*scale)/2)/scale,y=(e.clientY-r.top-(r.height-352*scale)/2)/scale;const s=stations.find(s=>Math.hypot(x-s.x,y-s.y)<62);if(s)action('station:'+s.role);});
function draw(now){const dt=Math.min((now-last)/1000,.04);last=now;const canvas=document.querySelector('#world');if(canvas){let dx=(keys.has('arrowright')||keys.has('d')?1:0)-(keys.has('arrowleft')||keys.has('a')?1:0),dy=(keys.has('arrowdown')||keys.has('s')?1:0)-(keys.has('arrowup')||keys.has('w')?1:0);if(!modal.open&&(dx||dy)){const length=Math.hypot(dx,dy);const nx=Math.max(32,Math.min(608,pos.x+dx/length*115*dt)),ny=Math.max(128,Math.min(318,pos.y+dy/length*115*dt));const blocked=(x,y)=>((x>48&&x<208&&y>208&&y<280)||(x>416&&x<592&&y>208&&y<280)||(x>300&&x<344&&y>244&&y<284));if(!blocked(nx,pos.y))pos.x=nx;if(!blocked(pos.x,ny))pos.y=ny;direction=dx<0?1:dx>0?2:dy<0?3:0;frame=Math.floor(now/140)%4;}else frame=0;const c=canvas.getContext('2d');c.imageSmoothingEnabled=false;c.clearRect(0,0,640,352);if(bg.complete&&bg.naturalWidth)c.drawImage(bg,0,0,640,352);const sprite=(x,y,dir,f)=>{const im=crewFrames[dir*4+f];if(im?.complete&&im.naturalWidth)c.drawImage(im,Math.round(x-24),Math.round(y-42),48,48);};stations.forEach(s=>{sprite(s.x+40,s.y,0,0);const near=Math.hypot(s.x-pos.x,s.y-pos.y)<110;c.fillStyle=near?'#ffe090':'#dbe9d4';c.fillRect(s.x-4,s.y-16,8,8);c.fillStyle='#142237';c.fillRect(s.x-35,s.y+12,70,17);c.fillStyle='#f4e7ba';c.font='11px monospace';c.textAlign='center';c.fillText(['WORKSHOP','BIOLOGY','COMMS','LEAD'][s.role],s.x,s.y+24);});sprite(pos.x,pos.y,direction,frame);c.fillStyle='#ffe096';c.fillRect(Math.round(pos.x-3),Math.round(pos.y-47),6,3);}requestAnimationFrame(draw);}render();requestAnimationFrame(draw);
